#include "../charge_compiler/json.hpp"
#include "C_edge_operator_v2.hpp"
#include <iostream>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
int main(int argc,char**argv){try{
 require(argc==2,"usage CONFIG");auto cfg=Json::read(argv[1]);double deadline=cfg.at("deadline_uptime").num();uint64_t nodes=cfg.at("node_count").integer();auto check=[&](){require(now()<deadline,"edge graph evaluation deadline");};capacitance::EdgeGraph graph(cfg.at("matrix").str(),nodes,cfg.at("maximum_adjacency_bytes").integer(),check,cfg.at("zero_rows").str());std::vector<double> voltage;voltage.reserve(nodes);
 if(cfg.at("vector_mode").str()=="explicit"){for(auto&v:cfg.at("voltage").arr())voltage.push_back(v.num());}
 else if(cfg.at("vector_mode").str()=="vertex_pattern"){for(uint64_t i=0;i<nodes;i++)voltage.push_back(double(i%65521)/32768.0);}
 else{require(cfg.at("vector_mode").str()=="conductor_constants","known edge vector mode");std::ifstream map(cfg.at("components").str(),std::ios::binary);require(bool(map),"component vector map open");char h[24];map.read(h,24);require(bool(map)&&std::string(h,8)=="CNETDOF1"&&sparse::load(h+8)==nodes,"component vector map dimensions");uint64_t nets=sparse::load(h+16);for(uint64_t i=0;i<nodes;i++){uint32_t component;map.read((char*)&component,4);require(bool(map)&&component<nets,"complete component vector map");voltage.push_back(double(component%31)/16.0);}char extra;require(!map.get(extra)&&map.eof(),"component vector map end");}
 std::vector<long double> current;Json timings=Json::array();require(!cfg.at("threads").arr().empty(),"requested thread controls");for(auto&t:cfg.at("threads").arr()){int threads=t.integer();double started=now();auto value=graph.apply(voltage,check,threads);double elapsed=now()-started;if(!current.empty()){require(current.size()==value.size(),"parallel graph vector size");for(uint64_t i=0;i<nodes;i++)require(current[i]==value[i],"bit-identical graph currents across thread counts");}current=std::move(value);Json timing=Json::object();timing["threads"]=threads;timing["apply_seconds_nonisolated"]=elapsed;timings.push(timing);}auto zero=read_zero_C_mask(cfg.at("zero_rows").str(),nodes);std::vector<sparse::Sum> reference(nodes);uint64_t records=0;{sparse::Reader input(cfg.at("matrix").str());sparse::Record r;while(input.next(r)){if(records++%10000==0)check();uint32_t i=r.key>>32,j=r.key&UINT32_MAX;if(i==j||r.value==0||zero[i]||zero[j])continue;long double flow=(-r.value)*(static_cast<long double>(voltage[i])-static_cast<long double>(voltage[j]));reference[i].add(flow);reference[j].add(-flow);}}uint64_t mismatched=0;for(uint64_t i=0;i<nodes;i++)mismatched+=reference[i].value()!=current[i];require(mismatched==0,"all graph rows match independent streamed edge scatter");uint64_t nonzero=0;long double maximum=0;sparse::Sum norm;for(auto v:current){nonzero+=v!=0;maximum=std::max(maximum,std::fabs(v));norm.add(std::fabs(v));}Json report=Json::object();report["thread_apply_timings"]=timings;report["all_requested_thread_vectors_bit_identical"]=true;report["independent_streamed_edge_scatter_matches_every_row"]=true;report["node_count"]=I(nodes);report["edges"]=I(graph.edges);report["nonzero_row_currents"]=I(nonzero);report["maximum_absolute_current"]=double(maximum);report["absolute_current_sum"]=double(norm.value());report["exact_conductor_constant_annihilation"]=nonzero==0;report["vector_mode"]=cfg.at("vector_mode");report["stored_diagonal_coefficients_used"]=false;report["full_matrix_passivity_verified"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;
 if(nodes<=100){Json currents=Json::array();for(auto v:current)currents.push(double(v));report["currents"]=currents;}std::ofstream out(cfg.at("report").str());out<<report.dump()<<'\n';require(bool(out),"edge graph report close");return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
